/**
 * Returns the RSJ Types & Thickness lookup table (cleaned "RSJ <dims>" group key -> thickness in mm). Used to auto-resolve thickness for NTLT/RSJ marks. Public (read-only).

 * @summary List RSJ thickness lookup entries
 */
export const ListRsjThicknessResponseItem = zod.object({
  "groupKey": zod.string().describe('Cleaned \"RSJ <dims>\" section group key.'),
  "thicknessMm": zod.number().describe('Thickness in mm for this RSJ type.'),
  "updatedAt": zod.string().optional()
})
export const ListRsjThicknessResponse = zod.array(ListRsjThicknessResponseItem)


/**
 * Upserts one RSJ lookup entry keyed by the cleaned "RSJ <dims>" group key. Requires authentication. RSJ marks with this group key resolve to the new thickness on the next read (live recompute).

 * @summary Create or update an RSJ thickness entry
 */
export const UpsertRsjThicknessBody = zod.object({
  "groupKey": zod.string(),
  "thicknessMm": zod.number()
})

export const UpsertRsjThicknessResponse = zod.object({
  "groupKey": zod.string().describe('Cleaned \"RSJ <dims>\" section group key.'),
  "thicknessMm": zod.number().describe('Thickness in mm for this RSJ type.'),
  "updatedAt": zod.string().optional()
})


/**
 * Removes one RSJ lookup entry. Requires authentication. The group key is passed as a query param (it can contain spaces) to avoid path-segment encoding issues.

 * @summary Delete an RSJ thickness entry
 */
export const DeleteRsjThicknessQueryParams = zod.object({
  "groupKey": zod.coerce.string()
})


/**
 * Parses the VTPL item master spreadsheet (XLS or XLSX, data from row 5 onward, columns: Select / ItemCode / ItemName / SubGroup / GroupName / Category / Grade / SectionWt / ThicknessMM). Upserts all rows into the item_master table (keyed on item_code) and clears the thickness cache so the new lookup takes effect immediately. Requires authentication.

 * @summary Upload item master XLS/XLSX
 */
export const UploadItemMasterBody = zod.object({
  "file": zod.instanceof(File)
})

export const UploadItemMasterResponse = zod.object({
  "totalRows": zod.number().describe('Total data rows parsed from the uploaded file.'),
  "upserted": zod.number().describe('Number of rows successfully upserted into item_master.'),
  "rowsWithThickness": zod.number().describe('Rows that have a non-null positive thickness_mm value.')
})


/**
 * Returns all item_master rows that have a thickness value (excluding FG JOB WORK), grouped by group_name and sorted alphabetically within each group. Used by the Thickness page to display a read-only reference table. Public (read-only).

 * @summary Item master thickness rows grouped by category
 */
export const ListItemMasterThicknessRowsResponseItem = zod.object({
  "groupName": zod.string().describe('The group_name value (e.g. \"PIPE\", \"RSJ POLE\", \"FLAT\").'),
  "items": zod.array(zod.object({
  "itemCode": zod.string(),
  "itemName": zod.string(),
  "thicknessMm": zod.number()
}))
})
export const ListItemMasterThicknessRowsResponse = zod.array(ListItemMasterThicknessRowsResponseItem)


/**
 * Returns summary statistics for the currently loaded item master: total row count, rows with a thickness value (non-JW, non-FG JOB WORK), and the timestamp of the most recently upserted row. Used by the admin upload card to show whether a master is loaded and when it was last updated. Public (read-only).

 * @summary Item master statistics
 */
export const GetItemMasterStatsResponse = zod.object({
  "totalRows": zod.number().describe('Total rows in the item_master table.'),
  "rowsWithThickness": zod.number().describe('Rows with a non-null positive thickness (non-JW, non-FG JOB WORK).'),
  "lastUploadedAt": zod.string().nullable().describe('ISO timestamp of the most recently updated row, or null when the table is empty.')
})


/**
 * Returns manual thickness values keyed by mark_id (used for NTLT/GENERAL and any hand-pinned mark). These survive re-imports. Public (read-only).

 * @summary List manual thickness pins
 */
export const ListManualThicknessResponseItem = zod.object({
  "markId": zod.string().describe('Mark identity (mark_id) the manual thickness is pinned to.'),
  "thicknessMm": zod.number().describe('Manually entered thickness in mm.'),
  "updatedAt": zod.string().optional()
})
export const ListManualThicknessResponse = zod.array(ListManualThicknessResponseItem)


/**
 * Upserts one manual thickness value keyed by mark_id. Requires authentication. The mark resolves to this value (source "manual") on the next read and the value persists across re-imports.

 * @summary Create or update a manual thickness pin
 */
export const UpsertManualThicknessBody = zod.object({
  "markId": zod.string(),
  "thicknessMm": zod.number()
})

export const UpsertManualThicknessResponse = zod.object({
  "markId": zod.string().describe('Mark identity (mark_id) the manual thickness is pinned to.'),
  "thicknessMm": zod.number().describe('Manually entered thickness in mm.'),
  "updatedAt": zod.string().optional()
})


/**
 * Removes one manual thickness pin (the mark reverts to auto/unset). Requires authentication. The mark id is passed as a query param (it can contain backslashes and spaces) to avoid path-segment encoding issues.

 * @summary Delete a manual thickness pin
 */
export const DeleteManualThicknessQueryParams = zod.object({
  "markId": zod.coerce.string()
})


/**
 * For all marks in the given import that are not already manually pinned, runs the item-master exact→stripped key lookup and bulk-upserts any matches into manual_thickness. Clears the thickness and serialised-records caches so the next /records fetch reflects the new pins. Requires auth.

 * @summary Bulk-apply item master thickness to unset marks
 */
export const ApplyItemMasterThicknessBody = zod.object({
  "importId": zod.number()
})

export const ApplyItemMasterThicknessResponse = zod.object({
  "applied": zod.number().describe('Number of marks that were matched by the item master and pinned.'),
  "noMatch": zod.number().describe('Number of marks that had no item master match and remain unset.'),
  "alreadyPinned": zod.number().describe('Number of marks skipped because they already had a manual pin.')
})


/**
 * Accepts a multipart .xlsx/.xls file. Detects a header row containing "mark" and "thickness" columns (case-insensitive); falls back to col-0=markId, col-1=thickness when no header is found. Bulk-upserts all valid rows into manual_thickness and clears the thickness cache. Requires auth.

 * @summary Bulk-import thickness pins from an Excel file
 */
